package com.example.starter.repo;

import com.example.starter.domain.Point;

import java.util.List;

/**
 * 审核不可变结果记录。
 *
 * @param reviewId        审核记录唯一标识
 * @param routeId         航线标识
 * @param routeVersion    审核时的航线版本
 * @param airspaceVersion 审核时的空域版本
 * @param conclusion      CLEAR / BLOCKED
 * @param hitZoneIds      命中 zoneId（字典序去重）
 * @param pointsSnapshot  审核时航点不可变快照
 * @param requestId       提交审核的请求标识
 * @param createdAt       创建时间（epoch 毫秒）
 */
public record ReviewPo(String reviewId, String routeId, int routeVersion, long airspaceVersion,
                       String conclusion, List<String> hitZoneIds, List<Point> pointsSnapshot,
                       String requestId, long createdAt) {
}
package com.example.starter.repo;

/**
 * 幂等去重记录。
 *
 * @param requestId    请求唯一标识
 * @param requestKind  请求类型（ZONE_CREATE 等）
 * @param requestHash  规范化参数哈希（SHA-256）
 * @param responseJson 首次成功响应 JSON
 * @param createdAt    创建时间（epoch 毫秒）
 */
public record DedupPo(String requestId, String requestKind, String requestHash,
                      String responseJson, long createdAt) {
}
package com.example.starter.repo;

import com.example.starter.domain.Point;

import java.util.List;

/**
 * 航线当前状态记录（点列为当前版本的点）。
 *
 * @param routeId 航线唯一标识
 * @param version 当前航线版本（从 1 开始）
 * @param points  当前版本有序航点
 */
public record RoutePo(String routeId, int version, List<Point> points) {
}
package com.example.starter.repo;

/**
 * 禁飞区持久化记录。
 *
 * @param zoneId         禁飞区唯一标识
 * @param xMin           左边界（含），米
 * @param yMin           下边界（含），米
 * @param xMax           右边界（含），米
 * @param yMax           上边界（含），米
 * @param status         ACTIVE / REVOKED
 * @param createdVersion 创建后生效的全局空域版本
 * @param revokedVersion 撤销后生效的全局空域版本；null 表示仍有效
 */
public record ZonePo(String zoneId, int xMin, int yMin, int xMax, int yMax,
                     String status, long createdVersion, Long revokedVersion) {
}
package com.example.starter.domain;

/** 审核结论：命中任一有效禁飞区为 BLOCKED，否则 CLEAR。 */
public enum ReviewConclusion {
    /** 航线与全部有效禁飞区均不相交。 */
    CLEAR,
    /** 航线有点或线段与至少一个有效禁飞区相交（含边界接触）。 */
    BLOCKED
}
package com.example.starter.domain;

/** 禁飞区状态：只能创建（ACTIVE）或撤销（REVOKED）。 */
public enum ZoneStatus {
