static final String KIND_PERMIT_CREATE = "PERMIT_CREATE";
static final String KIND_PERMIT_REVOKE = "PERMIT_REVOKE";
static final int MAX_ACTIVE_PERMITS = 20;

public MutationResponse createPermit(PermitCreateRequest request) {
    return withIdempotency(request.requestId(), KIND_PERMIT_CREATE, canonicalHash(request), () -> {
        if (request.startEpochSecond() >= request.endEpochSecond()) {
            throw new ApiException(BAD_REQUEST, "INVALID_PERMIT_INTERVAL", ...);
        }
        long airspaceVersion = airspaceRepo.getGlobalVersionForUpdate();
        RoutePo route = routeRepo.findRouteForUpdate(request.routeId());
        if (route == null) throw 404 ROUTE_NOT_FOUND;
        if (route.version() != request.routeVersion()) throw 409 VERSION_CONFLICT;
        if (route.points().size() != 2) throw 400 PERMIT_REQUIRES_TWO_POINT_ROUTE;
        Point a = route.points().get(0), b = route.points().get(1);
        // 原禁飞审查：两点连线不得命中任何有效禁飞区
        List<ZonePo> activeZones = airspaceRepo.findActiveZones();
        Set<String> hits = new TreeSet<>();
        for (zone : activeZones) if (Geometry.polylineHitsRectangle(route.points(), ...)) hits.add;
        if (!hits.isEmpty()) throw new ApiException(CONFLICT, "PERMIT_ROUTE_BLOCKED", "..." + hits);
        // 活动许可上限
        List<PermitPo> active = permitRepo.findActivePermits();
        if (active.size() >= MAX_ACTIVE_PERMITS) throw 409 PERMIT_LIMIT_EXCEEDED;
        // 间隔审查
        List<String> conflicts = new ArrayList<>();
        for (PermitPo other : active) {
            List<Point> pts = other.pointsSnapshot();
            Point c = pts.get(0), d = pts.get(1);
            OptionalDouble minSq = Motion.minDistanceSqOverOverlap(
                a.x(), a.y(), b.x(), b.y(), request.startEpochSecond(), request.endEpochSecond(),
                c.x(), c.y(), d.x(), d.y(), other.startEpochSecond(), other.endEpochSecond());
            if (minSq.isPresent() && minSq.getAsDouble() < Motion.MIN_SEPARATION_SQ) conflicts.add(other.permitId());
        }
        if (!conflicts.isEmpty()) throw new ApiException(UNPROCESSABLE_ENTITY, "PERMIT_SEPARATION_CONFLICT", msg, conflicts);
        String permitId = "pm_" + UUID.randomUUID();
        PermitPo po = new PermitPo(permitId, ..., List.of(a,b), "ACTIVE", request.requestId(), nowMillis(), null);
        permitRepo.insertPermit(po);
        return new MutationResponse(request.requestId(), false, toResult(po));
    });
}
