```java
package com.example.starter.domain;

/**
 * 两点匀速直线运动的间隔计算。
 * 许可在 [startSecond, endSecond)（左闭右开，UTC 整秒）内沿两点连线匀速运动。
 */
public final class Motion {

    private Motion() {
    }

    /** 最小安全间隔（米）。 */
    public static final double MIN_SEPARATION_METERS = 10.0d;

    /**
     * 计算两条匀速直线运动在共同有效区间内的最小距离平方（平方米）。
     * 共同区间为 [max(s1,s2), min(e1,e2))，左闭右开；端点相接（max>=min）无共同占用。
     * 通过相对位置与相对速度求二次函数最小值，不做端点比较或每秒采样，不提前舍入。
     *
     * @return 共同区间内的最小距离平方；无共同占用时返回 OptionalDouble.empty()
     */
    public static OptionalDouble minDistanceSqOverOverlap(
            double ax, double ay, double bx, double by, long s1, long e1,
            double cx, double cy, double dx, double dy, long s2, long e2) {
        long t0 = Math.max(s1, s2);
        long t1 = Math.min(e1, e2);
        if (t0 >= t1) {
            return OptionalDouble.empty();
        }
        double v1x = (bx - ax) / (e1 - s1);
        double v1y = (by - ay) / (e1 - s1);
        double v2x = (dx - cx) / (e2 - s2);
        double v2y = (dy - cy) / (e2 - s2);
        // 相对位置 r(t) = r0 + rv * (t - t0)
        double r0x = (ax + v1x * (t0 - s1)) - (cx + v2x * (t0 - s2));
        double r0y = (ay + v1y * (t0 - s1)) - (cy + v2y * (t0 - s2));
        double rvx = v1x - v2x;
        double rvy = v1y - v2y;
        double denom = rvx * rvx + rvy * rvy;
        double dt = 0.0d;
        if (denom > 0.0d) {
            dt = -(r0x * rvx + r0y * rvy) / denom;
            // 共同区间右开：t1 不占用，但若极小值在 t1 处取得，开区间内的值任意接近它，
            // 因此按闭区间端点评估与开区间下确界一致
            double maxDt = t1 - t0;
            if (dt < 0.0d) dt = 0.0d; else if (dt > maxDt) dt = maxDt;
        }
        double dxr = r0x + rvx * dt;
        double dyr = r0y + rvy * dt;
        return OptionalDouble.of(dxr * dxr + dyr * dyr);
    }

    /** 判断共同区间内的最小距离是否达到最小安全间隔（恰好等于也算安全）。 */
    public static boolean isSeparationSafe(...) { ... }
}
