    }

    /** 按 permitId 查询许可（含已撤销的历史轨迹与版本证据）。 */
    @GetMapping("/permits/{permitId}")
    public PermitResultDto getPermit(@PathVariable String permitId) {
        return service.getPermit(permitId);
    }

    /** 按 reviewId 查询历史审核结果（保留原结论）。 */
