        PermitResult delayed = dataOf(service.createPermit(permitReq("bob", "rb", 1, 11, 22)));
        assertEquals("ACTIVE", delayed.status());
        assertEquals(2, jdbc.queryForObject("SELECT COUNT(*) FROM permit", Integer.class));
    }

